-- R1-FIX VARIANT (draft/r1-fix-f3-acl-locks; PROPOSAL ONLY, NOT APPLIED). GENERATED by db/proposed/r1-fix-f3-acl-locks/build-variants.mjs from 10a-privacy-dependency/ROLLBACK-1C_PROPOSED.sql.
-- Differences from the original, and nothing else: (1) lock_timeout 5s + advisory lock + lock_timeout 5s first in the transaction (byte-identical otherwise: the original text follows this header, with these statements inserted after its first BEGIN;).
-- Do not edit by hand: re-run the generator (node build-variants.mjs --check fails if this file drifts from its original).
-- ROLLBACK-1C_PROPOSED.sql : undo APPLY-1C-grant-narrowing_PROPOSED.sql. PROPOSAL ONLY, NOT APPLIED.
--
-- Restores the privileges that existed immediately BEFORE 1C (= after APPLY-1 + APPLY-92), taken from the deterministic APPLY-1 text and from
-- PRECHECK-RESULTS P-10 (anon + authenticated held ALL on profile_content before anything). It then proves the restore by fingerprint.
--
-- PLACEHOLDER (an unfilled one makes the final fingerprint check fail, which aborts the whole transaction; nothing is changed):
--   {{PRE_1C_FINGERPRINT}}  = the md5 printed by PRECHECK-10A block H on prod IMMEDIATELY BEFORE 1C was applied (save it with the backup).
--
-- Order notes
--   * If APPLY-2 ran after 1C, run ROLLBACK-2-after-1C_PROPOSED.sql first (the stock ROLLBACK-2.sql re-grants INSERT/UPDATE on account_type/status, i.e. it would undo
--     the narrowing by itself). With APPLY-2 still in effect the fingerprint check below will refuse (anon SELECT differs), by design.
--   * If you only want the pre-APPLY-1 world back, run this file first, then ROLLBACK-1 / ROLLBACK-2 (their column REVOKEs are then harmless no-ops).
--   * Rolling back re-opens: owner self-set of account_type/status; TRUNCATE on profile_content; events.submitted_by readable; get_approved_profile executable.

BEGIN;
-- R1-LOCK: serialise pack runs. pg_advisory_xact_lock(2979301232487107403) = signed int64 of the first 8 bytes of sha256("keepitil-web db/proposed pack-run-serializer v1"); the SAME key is used by every APPLY/ROLLBACK pack,
-- so a second run (any pack) WAITS here until the first transaction commits or rolls back (transaction-scoped: released automatically). The wait is BOUNDED: lock_timeout = 5s is set
-- immediately BEFORE the lock (a lock_timeout set after a lock statement cannot bound that statement's own wait), so a second runner fails cleanly with SQLSTATE 55P03 (lock_not_available)
-- after ~5 s and changes nothing; it is set again immediately AFTER the lock so the same bound covers every later lock wait of the pack (SET LOCAL: this transaction only).
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- state guard: only roll back from the 1C target (or an already-restored pre-1C state, which makes this idempotent)
DO $g$
DECLARE
  p text; have text[]; want_post text[];
  a22   text[] := ARRAY['slug','display_name','handle','location','bio','tagline','pronouns','book_email','about','links','links_label','badges','account_type','status','avatar_url','cover_url','cover_mobile_url','socials','highlights','updated_at','profile_public','public_fields'];
  ins19 text[] := ARRAY['slug','display_name','handle','location','bio','about','links','links_label','socials','avatar_url','cover_url','cover_mobile_url','profile_public','public_fields','updated_at','tagline','pronouns','book_email','highlights'];
  upd14 text[] := ARRAY['display_name','handle','location','bio','about','links','links_label','socials','avatar_url','cover_url','cover_mobile_url','profile_public','public_fields','updated_at'];
BEGIN
  FOREACH p IN ARRAY ARRAY['INSERT','UPDATE'] LOOP
    SELECT COALESCE(array_agg(a.attname::text), ARRAY[]::text[]) INTO have FROM pg_attribute a
     WHERE a.attrelid = 'public.profile_meta'::regclass AND a.attnum > 0 AND NOT a.attisdropped AND has_column_privilege('authenticated', 'public.profile_meta', a.attname, p);
    want_post := CASE p WHEN 'INSERT' THEN ins19 ELSE upd14 END;
    IF NOT (NOT EXISTS (SELECT 1 FROM unnest(a22) x WHERE NOT (x = ANY (have))) AND NOT EXISTS (SELECT 1 FROM unnest(have) x WHERE NOT (x = ANY (a22))))
       AND NOT (NOT EXISTS (SELECT 1 FROM unnest(want_post) x WHERE NOT (x = ANY (have))) AND NOT EXISTS (SELECT 1 FROM unnest(have) x WHERE NOT (x = ANY (want_post)))) THEN
      RAISE EXCEPTION 'rollback-1C guard: authenticated column-% set on profile_meta is neither the 1C target nor the pre-1C set (%); nothing changed', p, have;
    END IF;
  END LOOP;
END
$g$;

-- profile_meta: column grants back to the APPLY-1 set (22/22); REFERENCES + TRIGGER back for anon and authenticated (APPLY-1 never removed them)
REVOKE INSERT (slug, display_name, handle, location, bio, about, links, links_label, socials, avatar_url, cover_url, cover_mobile_url, profile_public, public_fields, updated_at, tagline, pronouns, book_email, highlights)
  ON TABLE public.profile_meta FROM authenticated;
REVOKE UPDATE (display_name, handle, location, bio, about, links, links_label, socials, avatar_url, cover_url, cover_mobile_url, profile_public, public_fields, updated_at)
  ON TABLE public.profile_meta FROM authenticated;
GRANT INSERT (slug, display_name, handle, location, bio, tagline, pronouns, book_email, about, links, links_label, badges, account_type, status, avatar_url, cover_url, cover_mobile_url, socials, highlights, updated_at, profile_public, public_fields)
  ON TABLE public.profile_meta TO authenticated;
GRANT UPDATE (slug, display_name, handle, location, bio, tagline, pronouns, book_email, about, links, links_label, badges, account_type, status, avatar_url, cover_url, cover_mobile_url, socials, highlights, updated_at, profile_public, public_fields)
  ON TABLE public.profile_meta TO authenticated;
GRANT REFERENCES, TRIGGER ON TABLE public.profile_meta TO anon, authenticated;

-- profile_owners: authenticated had SELECT + REFERENCES + TRIGGER after APPLY-1 (anon had nothing)
GRANT REFERENCES, TRIGGER ON TABLE public.profile_owners TO authenticated;

-- profile_content: P-10 captured ALL for both roles; APPLY-1 never touched it
GRANT ALL ON TABLE public.profile_content TO anon, authenticated;

-- events.submitted_by (APPLY-92 granted it as part of the 45)
GRANT SELECT (submitted_by) ON TABLE public.events TO anon, authenticated;

-- PostgreSQL 17+ MAINTAIN: held by anon/authenticated on profile_meta and profile_content (GRANT ALL, P-10) and by authenticated on profile_owners (anon lost everything there in APPLY-1)
DO $m$
BEGIN
  IF current_setting('server_version_num')::int >= 170000 THEN
    EXECUTE 'GRANT MAINTAIN ON TABLE public.profile_meta TO anon, authenticated';
    EXECUTE 'GRANT MAINTAIN ON TABLE public.profile_owners TO authenticated';
    EXECUTE 'GRANT MAINTAIN ON TABLE public.profile_content TO anon, authenticated';
  END IF;
END
$m$;

-- get_approved_profile (APPLY-1: REVOKE FROM PUBLIC, GRANT TO anon, authenticated)
DO $$
BEGIN
  IF to_regprocedure('public.get_approved_profile(uuid,text)') IS NOT NULL THEN
    GRANT EXECUTE ON FUNCTION public.get_approved_profile(uuid, text) TO anon, authenticated;
  END IF;
END $$;

-- proof of an exact restore: same fingerprint expression as PRECHECK-10A block H
DO $fp$
DECLARE v text;
BEGIN
  SELECT md5(string_agg(line, E'\n' ORDER BY line)) INTO v FROM (
    SELECT 'T|' || c.relname || '|' || CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END || '|' || a.privilege_type || '|' || a.is_grantable::text AS line
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace, LATERAL aclexplode(c.relacl) a
     WHERE n.nspname = 'public' AND c.relname IN ('profile_meta','profile_owners','profile_content','events','applications')
    UNION ALL
    SELECT 'C|' || c.relname || '.' || at.attname || '|' || CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END || '|' || a.privilege_type || '|' || a.is_grantable::text
      FROM pg_attribute at JOIN pg_class c ON c.oid = at.attrelid JOIN pg_namespace n ON n.oid = c.relnamespace, LATERAL aclexplode(at.attacl) a
     WHERE n.nspname = 'public' AND c.relname IN ('profile_meta','profile_owners','profile_content','events','applications') AND at.attnum > 0 AND NOT at.attisdropped AND at.attacl IS NOT NULL
    UNION ALL
    SELECT 'F|' || p.oid::regprocedure::text || '|' || CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee)::text END || '|' || a.privilege_type || '|' || a.is_grantable::text
      FROM pg_proc p, LATERAL aclexplode(p.proacl) a WHERE p.oid = to_regprocedure('public.get_approved_profile(uuid,text)')
  ) s;
  IF v IS DISTINCT FROM '{{PRE_1C_FINGERPRINT}}' THEN
    RAISE EXCEPTION 'rollback-1C: privileges after restore (%) do not equal the saved pre-1C fingerprint; transaction aborted, nothing changed', v;
  END IF;
END
$fp$;

COMMIT;
